<script setup lang="ts">
import { onMounted, ref } from 'vue';
import { useRouter } from 'vue-router';
import { api, ApiError, errorText, mutationId, session } from '../api';
import type { PersonalProfile } from '../../../packages/contracts/src/index.js';
import AtlasIcon from '../components/AtlasIcon.vue';
import '../styles/atlas.css';
const router = useRouter(), profile = ref<PersonalProfile | null>(null), name = ref(''), current = ref(''), password = ref(''), confirm = ref(''), busy = ref(false), error = ref(''), message = ref(''); let key = mutationId(), lastName = '';
async function load() { error.value = ''; try { profile.value = await api('/me/profile'); name.value = profile.value!.displayName; } catch (e) { error.value = errorText(e); } }
onMounted(load);
async function saveName() { if (!profile.value || busy.value) return; if (lastName !== name.value) { key = mutationId(); lastName = name.value; } busy.value = true; error.value = ''; message.value = '';
  try { const result = await api<PersonalProfile>('/me/profile', 'PATCH', { displayName: name.value, baseVersion: profile.value.version, clientMutationId: key }); profile.value = result; if (session.value) session.value.user.displayName = result.displayName; message.value = '显示名称已保存。'; key = mutationId(); } catch (e) { const text = errorText(e); if (e instanceof ApiError && e.status === 409) await load(); error.value = text; } finally { busy.value = false; }
}
async function savePassword() { if (!profile.value || busy.value) return; error.value = ''; message.value = ''; if (password.value !== confirm.value) { error.value = '两次填写的新密码不一致。'; return; } if (!window.confirm('修改密码后，所有设备都需要重新登录，是否继续？')) return; busy.value = true;
  try { await api('/me/password', 'POST', { currentPassword: current.value, newPassword: password.value, baseVersion: profile.value.version }); current.value = ''; password.value = ''; confirm.value = ''; session.value = null; await router.replace('/me'); } catch (e) { error.value = errorText(e); } finally { busy.value = false; }
}
</script>
<template><section class="flow-view"><header class="flow-topbar"><button class="icon-button" aria-label="返回我的" :disabled="busy" @click="router.push('/me')"><AtlasIcon name="back"/></button><h2>个人设置</h2><span class="icon-button"/></header><div class="flow-scroll"><p v-if="error" class="flow-form-errors" role="alert">{{ error }}</p><p v-if="message" class="flow-save-state" role="status">{{ message }}</p><p v-if="!profile && !error">正在读取个人资料…</p><button v-if="!profile && error" class="text-button" @click="load">重新读取个人资料</button><template v-if="profile"><section class="settings-section"><h3>个人资料</h3><p class="small muted">账号：{{ profile.username }}</p><form @submit.prevent="saveName"><fieldset class="settings-fields" :disabled="busy"><div class="flow-field"><label for="profile-name">显示名称</label><input id="profile-name" v-model="name" required maxlength="80"></div><button class="primary" :disabled="name.trim() === profile.displayName">保存显示名称</button></fieldset></form></section><section class="settings-section"><h3>修改登录密码</h3><p class="small muted">新密码至少 12 位，保存后所有设备会话失效，请使用新密码重新登录。</p><form @submit.prevent="savePassword"><fieldset class="settings-fields" :disabled="busy"><div class="flow-field"><label for="current-password">当前密码</label><input id="current-password" v-model="current" type="password" required autocomplete="current-password" maxlength="128"></div><div class="flow-field"><label for="new-password">新密码</label><input id="new-password" v-model="password" type="password" required minlength="12" maxlength="128" autocomplete="new-password"></div><div class="flow-field"><label for="confirm-password">再次填写新密码</label><input id="confirm-password" v-model="confirm" type="password" required minlength="12" maxlength="128" autocomplete="new-password"></div><button class="primary">保存新密码并重新登录</button></fieldset></form></section></template></div></section></template>
